140	                    "forget should not be called on inode already removed from superblock"
141	                );
142	                error!("forget called on inode {ino} already removed from the superblock");
143	                return;
144	            }
145	        };
146	
147	        logging::record_name(inode.name());
148	        let new_lookup_count = inode.dec_lookup_count(n);
149	        if new_lookup_count == 0 {
